using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so we must explicitly preserve it.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF Core 9 uses only the raw key for "id" (e.g. "1").
            // Existing documents have id = "Blog|1". Preserve the legacy format.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws at runtime in EF Core 9. Removed below.
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: Sync I/O now throws by default in EF Core 9 Cosmos provider.
        // Existing sync code (ToList, SaveChanges) requires opt-in or migration to async.
        optionsBuilder.EnableThreadSafetyChecks(false);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

// Value generator that preserves the legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry) =>
        $"{entry.Metadata.GetDiscriminatorValue()}|{Guid.NewGuid()}";
}

